/** Host-owned destination and mandatory human confirmation for Daedal handoffs. @module */
import { Context, Service } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import type { Agent } from '@deepseek-ai/dsh-agent'
import type { ToolCallId } from '@deepseek-ai/dsh-llm'
import type {} from '@deepseek-ai/dsh-fs'
import type {} from '@deepseek-ai/dsh-subprocess'
import type {} from '@deepseek-ai/dsh-agent-presets'
import type {} from '@deepseek-ai/dsh-session-projection'
import type {} from '@deepseek-ai/dsh-user-questions'
import { HANDOFF_PATH, daedalPreset, destinationSchema, handoffSessionId, receiptSchema, taskSchema } from './protocol.ts'
import { isHostExecution } from './world.ts'
import type { HandoffResult } from './types.ts'
export type { HandoffResult } from './types.ts'

/** Deployment-owned destination; omitted leaves handoff unavailable. */
export interface Config {
  /** Separate host profile's HTTP origin, HTTPS except for loopback. */
  destinationUrl?: string
  /** Dedicated receiver token, supplied from host credentials, never model arguments. */
  token?: string
  /** Deadline for each destination request, excluding human review time. */
  timeoutMs: number
  /** Complete request and response byte ceiling. */
  maxBytes: number
}

declare module '@deepseek-ai/cordis' {
  interface Context {
    daedalHandoff: DaedalHandoff
  }
}

/** Configured transport with a human decision before every task dispatch. */
export class DaedalHandoff extends Service {
  static inject = ['agents', 'sessionProjections', 'userQuestions', 'fs', 'subprocess']
  static Config: z<Config> = z.object({
    destinationUrl: z.string(), token: z.string(),
    timeoutMs: z.number().step(1).min(1).default(15_000),
    maxBytes: z.number().step(1).min(1).default(65_536),
  })

  private readonly destination: { endpoint: URL; token: string } | undefined
  private readonly lifetime = new AbortController()
  private readonly pending = new Set<Promise<HandoffResult>>()

  constructor(ctx: Context, private readonly config: Config) {
    super(ctx, 'daedalHandoff')
    ctx.effect(() => async () => {
      this.lifetime.abort()
      await Promise.allSettled([...this.pending])
    }, 'daedal handoff requests')
    if (config.destinationUrl === undefined && config.token === undefined) return
    if (config.destinationUrl === undefined || config.token === undefined) {
      throw new Error('daedal-handoff requires both destinationUrl and token, or neither')
    }
    const url = new URL(config.destinationUrl)
    if (url.username || url.password || url.search || url.hash || url.pathname !== '/'
      || (url.protocol !== 'https:' && !(url.protocol === 'http:' && ['127.0.0.1', '[::1]'].includes(url.hostname)))
      || config.token.length < 32) throw new Error('daedal-handoff requires an HTTPS or loopback HTTP origin and a dedicated token of at least 32 characters')
    this.destination = { endpoint: new URL(HANDOFF_PATH, url), token: config.token }
  }

  /**
   * Review one complete task and dispatch only an exact human approval.
   * @param agent - exact live root Agent in a Daedal preset.
   * @param callId - current tool call identity, used for duplicate delivery protection.
   * @param task - title and complete summary including committed work and remaining steps.
   * @param signal - source operation cancellation; cancellation after dispatch can leave acceptance unknown.
   * @returns explicit rejection, unavailability, successful receipt, or uncertain acceptance with a destination id.
   */
  handoff(agent: Agent, callId: ToolCallId, task: { title: string; task: string }, signal: AbortSignal): Promise<HandoffResult> {
    const operation = this.transfer(agent, callId, task, AbortSignal.any([signal, this.lifetime.signal]))
      .finally(() => { this.pending.delete(operation) })
    this.pending.add(operation)
    return operation
  }

  private async transfer(
    agent: Agent, callId: ToolCallId, task: { title: string; task: string }, signal: AbortSignal,
  ): Promise<HandoffResult> {
    signal.throwIfAborted()
    const preset = daedalPreset.parse(this.ctx.sessionProjections.stateOf(agent.session, 'agentPreset'))
    if (this.ctx.agents.get(agent.id) !== agent || !this.ctx.agents.roots().includes(agent)) {
      throw new Error('Only a live root Daedal session can request host handoff; delegated agents must report the need to their parent.')
    }
    if (isHostExecution(this.ctx, agent)) {
      throw new Error('This session already runs on the host; perform authorized maintenance here.')
    }
    const transport = this.destination
    if (transport === undefined) return { status: 'unavailable', message: 'Host handoff is not configured. Ask the user to open a separate host-maintenance session; do not probe host paths from this session.' }
    const parsed = taskSchema.parse(task)
    const destination = destinationSchema.parse(await this.request(transport, 'GET', signal))
    const request = { sourceSessionId: agent.id, callId, preset, destination, ...parsed }
    const body = JSON.stringify(request)
    if (Buffer.byteLength(body) > this.config.maxBytes) throw new Error('Handoff exceeds the configured byte limit; shorten the task summary.')
    const answer = await this.ctx.userQuestions.ask({ agent, signal, questions: [{
      id: 'daedal-host-handoff', header: 'Host handoff',
      question: `Start a new host-maintenance session on ${destination.name}?`,
      detail: `Destination: ${destination.name}\nAddress: ${destination.url ?? transport.endpoint.origin}\nWorking directory: ${destination.cwd}\nMode: ${preset}\n\nThe new session runs on the host with that profile's permissions. This source session keeps its current access.\n\n# ${parsed.title}\n\n${parsed.task}`,
      options: [{ label: 'Start host session' }, { label: 'Stay here' }],
    }] })
    signal.throwIfAborted()
    if (this.ctx.agents.get(agent.id) !== agent
      || this.ctx.sessionProjections.stateOf(agent.session, 'agentPreset') !== preset) {
      throw new Error('The source session changed during review; request a new handoff.')
    }
    const decision = answer.answers.find(item => item.id === 'daedal-host-handoff')
    if (decision?.selected.length !== 1 || decision.selected[0] !== 'Start host session' || decision.custom?.trim()) {
      return { status: 'declined', message: 'No host session was started. Remain in the current environment.' }
    }
    const sessionId = handoffSessionId(request)
    try {
      const receipt = receiptSchema.parse(await this.request(transport, 'POST', signal, body))
      if (receipt.sessionId !== sessionId) throw new Error('Handoff receipt identity mismatch')
      return { status: 'started', sessionId, destination: destination.name, destinationUrl: destination.url ?? transport.endpoint.origin,
        message: 'Continue in the new host session. Stop host-maintenance work in this source session.' }
    } catch {
      // A failed or cancelled HTTP exchange cannot prove whether the destination admitted the task.
      return { status: 'unknown', sessionId, destinationUrl: destination.url ?? transport.endpoint.origin,
        message: 'Host acceptance is unknown. Inspect this session at the destination before requesting another handoff; do not automatically retry.' }
    }
  }

  private async request(
    transport: { endpoint: URL; token: string }, method: 'GET' | 'POST', signal: AbortSignal, body?: string,
  ): Promise<unknown> {
    const response = await fetch(transport.endpoint, {
      method, redirect: 'error', signal: AbortSignal.any([signal, AbortSignal.timeout(this.config.timeoutMs)]),
      headers: { authorization: `Bearer ${transport.token}`, 'content-type': 'application/json' },
      ...body === undefined ? {} : { body },
    })
    if (!response.ok) {
      await response.body?.cancel()
      throw new Error(`Host handoff destination refused the request (HTTP ${response.status}).`)
    }
    if (response.body === null) throw new Error('Host handoff destination returned no response body')
    const chunks: Uint8Array[] = []
    let length = 0
    for await (const chunk of response.body) {
      length += chunk.byteLength
      if (length > this.config.maxBytes) throw new Error('Host handoff response exceeds the configured byte limit')
      chunks.push(chunk)
    }
    return JSON.parse(Buffer.concat(chunks).toString('utf8')) as unknown
  }
}

export default DaedalHandoff

/** Private, versioned host-handoff request validation. @module */
import { createHash } from 'node:crypto'
import { z } from 'zod'
import { SessionId } from '@deepseek-ai/dsh-session'
import { ToolCallId } from '@deepseek-ai/dsh-llm'

/** Fixed authenticated endpoint shared by the two explicitly configured profiles. */
export const HANDOFF_PATH = '/daedal-handoff/v1'
/** Presets admitted by the handoff executor and receiver. */
export const daedalPreset = z.enum(['daedal', 'daedal-openai'])
/** Receiver-owned destination displayed verbatim before confirmation. */
export const destinationSchema = z.object({
  name: z.string().min(1), cwd: z.string().min(1),
  url: z.url().refine((value) => {
    const url = new URL(value)
    return ['http:', 'https:'].includes(url.protocol) && !url.username && !url.password
      && url.pathname === '/' && !url.search && !url.hash
  }).optional(),
}).strict()
/** Complete task transferred after human confirmation. */
export const taskSchema = z.object({ title: z.string().trim().min(1), task: z.string().trim().min(1) }).strict()
/** Wire request; the receiver bounds the complete UTF-8 body before parsing. */
export const requestSchema = z.object({
  sourceSessionId: z.string().min(1).transform(SessionId),
  callId: z.string().min(1).transform(ToolCallId),
  preset: daedalPreset,
  destination: destinationSchema,
  ...taskSchema.shape,
}).strict()
/** Receiver acknowledgement, without credentials or internal errors. */
export const receiptSchema = z.object({ sessionId: z.string().min(1).transform(SessionId), accepted: z.literal(true) }).strict()

/**
 * Derive the same identity for a repeated delivery of the exact approved request.
 * @param request - validated task and caller identity.
 * @returns destination Session id; changing any approved field changes the identity.
 */
export function handoffSessionId(request: z.input<typeof requestSchema>): SessionId {
  return SessionId(`handoff-${createHash('sha256').update(JSON.stringify(requestSchema.parse(request))).digest('hex')}`)
}

/** Authenticated handoff intake mounted only in a separate host Web profile. @module */
import { timingSafeEqual } from 'node:crypto'
import { isAbsolute } from 'node:path'
import { stat } from 'node:fs/promises'
import type { ServerResponse } from 'node:http'
import type { Context } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import { SessionId } from '@deepseek-ai/dsh-session'
import type { SessionPromptRequest } from '@deepseek-ai/dsh-api-session-controller'
import type {} from '@deepseek-ai/dsh-host-webserver'
import type {} from '@deepseek-ai/dsh-fs'
import type {} from '@deepseek-ai/dsh-subprocess'
import { HANDOFF_PATH, handoffSessionId, requestSchema, destinationSchema } from './protocol.ts'

export const name = 'daedal-handoff-receiver'
export const inject = ['webServer', 'sessionController', 'fs', 'subprocess']

/** Fixed host destination and bounded authenticated intake. */
export interface Config {
  /** Name displayed during source confirmation. */
  name: string
  /** Browser origin advertised for this host; transport may use a separate loopback origin. */
  publicUrl?: string
  /** Absolute destination workspace; callers cannot choose another directory. */
  cwd: string
  /** Dedicated shared secret known only to the two host control planes. */
  token: string
  /** Maximum complete UTF-8 request size. */
  maxBytes: number
  /** Deadline for reading and admitting a request; active intake is aborted on unload. */
  timeoutMs: number
}

export const Config: z<Config> = z.object({
  publicUrl: z.string(),
  name: z.string().required(), cwd: z.string().required(), token: z.string().required(),
  maxBytes: z.number().step(1).min(1).default(65_536),
  timeoutMs: z.number().step(1).min(1).default(15_000),
})

/** Send bounded protocol data without request bodies, credentials, or exception text. */
function respond(response: ServerResponse, status: number, body: object): void {
  response.writeHead(status, { 'content-type': 'application/json', 'cache-control': 'no-store' })
  response.end(JSON.stringify(body))
}

/**
 * Admit approved tasks into ordinary host Sessions through the Session Controller.
 * @param ctx - separately launched host profile with Web and Session APIs.
 * @param config - destination identity and authentication settings.
 */
export async function apply(ctx: Context, config: Config): Promise<void> {
  const host = Symbol.for('@deepseek-ai/dsh/host-execution-world')
  const assertHost = (): void => {
    if (ctx.fs.executionWorld !== host || ctx.subprocess.executionWorld !== host) {
      throw new Error('daedal-handoff receiver requires host filesystem and subprocess providers in a separate host profile')
    }
  }
  assertHost()
  if (!config.name.trim() || !isAbsolute(config.cwd) || config.token.length < 32) {
    throw new Error('daedal-handoff receiver requires a name, absolute cwd, and a dedicated token of at least 32 characters')
  }
  if (!(await stat(config.cwd)).isDirectory()) throw new Error('daedal-handoff destination cwd must be a directory')
  const destination = destinationSchema.parse({ name: config.name, cwd: config.cwd,
    ...config.publicUrl === undefined ? {} : { url: config.publicUrl },
  })
  const expected = Buffer.from(`Bearer ${config.token}`)
  const active = new Set<Promise<void>>()
  const admission = new Map<string, Promise<void>>()
  const lifetime = new AbortController()
  ctx.effect(() => async () => {
    lifetime.abort()
    await Promise.allSettled([...active])
  }, 'daedal-handoff receiver lifetime')
  ctx.effect(() => ctx.webServer.register({ kind: 'exact', path: HANDOFF_PATH, handler: (req, res) => {
    const signal = AbortSignal.any([lifetime.signal, AbortSignal.timeout(config.timeoutMs)])
    const stopIntake = (): void => { if (!req.complete) req.destroy() }
    signal.addEventListener('abort', stopIntake, { once: true })
    const work = (async () => {
      const actual = Buffer.from(req.headers.authorization ?? '')
      if (req.headers.origin !== undefined || actual.length !== expected.length || !timingSafeEqual(actual, expected)) {
        req.resume(); respond(res, 401, { error: 'Unauthorized handoff' }); return
      }
      assertHost()
      signal.throwIfAborted()
      if (req.method === 'GET') { respond(res, 200, destination); return }
      if (req.method !== 'POST') { req.resume(); respond(res, 405, { error: 'Use GET or POST' }); return }
      if (req.headers['content-type']?.split(';')[0]?.trim() !== 'application/json') {
        req.resume(); respond(res, 415, { error: 'Expected application/json' }); return
      }
      const chunks: Buffer[] = []
      let size = 0
      if (Number(req.headers['content-length']) > config.maxBytes) {
        req.resume(); respond(res, 413, { error: 'Handoff is too large' }); return
      }
      for await (const data of req) {
        const chunk = Buffer.from(data as Uint8Array)
        size += chunk.length
        if (size > config.maxBytes) { req.resume(); respond(res, 413, { error: 'Handoff is too large' }); return }
        chunks.push(chunk)
      }
      let value: unknown
      try { value = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks))) }
      catch { respond(res, 400, { error: 'Expected UTF-8 JSON' }); return }
      const parsed = requestSchema.safeParse(value)
      if (!parsed.success) { respond(res, 400, { error: 'Invalid handoff fields or Daedal mode' }); return }
      const request = parsed.data
      if (request.destination.name !== destination.name || request.destination.cwd !== destination.cwd
        || request.destination.url !== destination.url) {
        respond(res, 409, { error: 'Destination changed; request a new human confirmation' }); return
      }
      const sessionId = SessionId(handoffSessionId(request))
      let pending = admission.get(sessionId)
      if (pending === undefined) {
        pending = (async () => {
          assertHost()
          signal.throwIfAborted()
          await ctx.sessionController.create({ sessionId, cwd: config.cwd, agentPreset: request.preset })
          signal.throwIfAborted()
          assertHost()
          await ctx.sessionController.prompt({ sessionId,
            requestId: sessionId as unknown as SessionPromptRequest['requestId'], mode: 'queue',
            content: [{ type: 'text', text: `# ${request.title}\n\nThe user confirmed this handoff from Daedal session ${request.sourceSessionId} to ${config.name}. Continue the approved task below in this host session. The source session remains isolated.\n\n${request.task}` }],
          }, signal)
        })()
        admission.set(sessionId, pending)
      }
      try { await pending } finally { if (admission.get(sessionId) === pending) admission.delete(sessionId) }
      respond(res, 200, { sessionId, accepted: true })
    })().catch(() => {
      // Protocol errors intentionally omit host exception details and submitted task text.
      respond(res, 503, { error: 'Host handoff could not be acknowledged; inspect the destination session before retrying' })
    }).finally(() => { signal.removeEventListener('abort', stopIntake); active.delete(work) })
    active.add(work)
    return work
  } }), 'daedal-handoff receiver route')
}

/** Daedal-preset-only execution guidance and handoff tool. @module */
import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from '@deepseek-ai/dsh-tools'
import type {} from '@deepseek-ai/dsh-fs'
import type {} from '@deepseek-ai/dsh-subprocess'
import type {} from '@deepseek-ai/dsh-system-prompt'
import type {} from './index.ts'
import { isHostExecution } from './world.ts'

export const name = 'daedal-handoff-tool'
export const inject = ['tools', 'systemPrompt', 'fs', 'subprocess']

/** Install only in Daedal preset scopes. @param ctx - preset-owned registration context. */
export function apply(ctx: Context): void {
  ctx.systemPrompt.context({
    name: 'daedal:execution', order: ctx.systemPrompt.getContextOrder('SANDBOX_POLICY') + 2,
    text: ({ agent }) => {
      return isHostExecution(ctx, agent)
        ? 'Execution environment: host. Files and commands use this host profile and its permissions. Perform authorized host maintenance here; do not request another host handoff.'
        : 'Execution environment: isolated workspace. Workspace file and shell tools operate in isolation. Their paths, processes, and localhost do not identify the host running the harness. Permission changes cannot move this session onto the host. For updating or restarting the running harness, managing host services, or inspecting host-only files or processes, stop and call handoff_to_host with the complete task, committed branch or revision, and remaining steps. Do not search guessed host paths, probe host processes, retry blocked localhost requests, or invent unavailable tools. The action asks the user to confirm a separate host session. If unavailable or declined, report that and stop host work. Delegated agents must report the required handoff to their parent. After successful handoff, continue that work only in the destination session.'
    },
  })
  ctx.tools.register(defineTool({
    name: 'handoff_to_host',
    description: 'Request explicit user confirmation to transfer host-maintenance work from this isolated Daedal workspace to a new session on the configured host. Supply the complete task, relevant committed branch or revision, completed checks, and remaining steps. Use this as the only tool call in the response. It never changes this session’s execution environment or permissions.',
    parameters: {
      title: { type: 'string', required: true, description: 'Short title for the host task.' },
      task: { type: 'string', required: true, description: 'Complete task summary for user review and transfer, including committed work, checks, and remaining host steps. Exclude secrets.' },
    },
    output: {
      schema: { type: 'object', additionalProperties: false, properties: {
        status: { type: 'string', required: true }, message: { type: 'string', required: true },
        sessionId: { type: 'string' }, destination: { type: 'string' }, destinationUrl: { type: 'string' },
      } },
      render: (_args, result) => [{ type: 'text', text: JSON.stringify(result) }],
    },
    presentCall: args => ({ card: 'generic', title: 'Request host handoff', kind: 'other', rawInput: args }),
    async execute(args, exec) {
      if (exec.agent === undefined) throw new Error('Host handoff requires a live Daedal session')
      if (isHostExecution(ctx, exec.agent)) {
        throw new Error('This session already runs on the host; perform authorized maintenance here.')
      }
      const handoff = ctx.get('daedalHandoff')
      if (handoff === undefined) return { status: 'unavailable', message: 'Host handoff is not configured. Ask the user to start a separate host-maintenance session. Do not attempt host work here.' }
      return handoff.handoff(exec.agent, exec.callId, args, exec.signal)
    },
  }))
}

/** Model-visible handoff outcome, excluding destination credentials. @module */
import type { SessionId } from '@deepseek-ai/dsh-session'

/** Receipt or refusal produced by one confirmed handoff attempt. */
export interface HandoffResult {
  status: 'unavailable' | 'declined' | 'started' | 'unknown'
  message: string
  sessionId?: SessionId
  destination?: string
  destinationUrl?: string
}

